App.Http.Booking=(function(){const $selectDate=$('#select-date');const $selectService=$('#select-service');const $selectProvider=$('#select-provider');const $availableHours=$('#available-hours');const $captchaHint=$('#captcha-hint');const $captchaTitle=$('.captcha-title');const MONTH_SEARCH_LIMIT=2;const moment=window.moment;function bookingEndpoint(endpoint){const providerSlug=vars('fixed_provider_slug');const route=providerSlug?`booking/${providerSlug}/${endpoint}`:`booking/${endpoint}`;return App.Utils.Url.siteUrl(route);}
let unavailableDatesBackup;let selectedDateStringBackup;let processingUnavailableDates=false;let searchedMonthStart;let searchedMonthCounter=0;function getAvailableHours(selectedDate){$availableHours.empty();const serviceId=$selectService.val();let serviceDuration=15;const service=vars('available_services').find((availableService)=>Number(availableService.id)===Number(serviceId),);if(service){serviceDuration=service.duration;}
const appointmentId=vars('manage_mode')?vars('appointment_data').id:null;const url=bookingEndpoint('get_available_hours');const data={csrf_token:vars('csrf_token'),service_id:$selectService.val(),provider_id:$selectProvider.val(),selected_date:selectedDate,service_duration:serviceDuration,manage_mode:Number(vars('manage_mode')||0),appointment_id:appointmentId,};$.post(url,data).done((response)=>{$availableHours.empty();if(response.length>0){let providerId=$selectProvider.val();if(providerId==='any-provider'){for(const availableProvider of vars('available_providers')){if(availableProvider.services.indexOf(Number(serviceId))!==-1){providerId=availableProvider.id;break;}}}
const provider=vars('available_providers').find((availableProvider)=>Number(providerId)===Number(availableProvider.id),);if(!provider){throw new Error('Could not find provider.');}
const providerTimezone=provider.timezone;const selectedTimezone=$('#select-timezone').val();const timeFormat=vars('time_format')==='regular'?'h:mm a':'HH:mm';response.forEach((availableHour)=>{const availableHourMoment=moment.tz(selectedDate+' '+availableHour+':00',providerTimezone).tz(selectedTimezone);if(availableHourMoment.format('YYYY-MM-DD')!==selectedDate){return;}
const $availableHourButton=$('<button/>',{'class':'btn btn-outline-secondary w-100 shadow-none available-hour','data':{'value':availableHour,},'text':availableHourMoment.format(timeFormat),}).attr('data-start-timestamp',availableHourMoment.valueOf());$availableHours.append($availableHourButton);});if(App.Pages.Booking.manageMode){$('.available-hour').removeClass('selected-hour').filter((index,availableHourEl)=>$(availableHourEl).data('value')===moment(vars('appointment_data').start_datetime).format('HH:mm'),).addClass('selected-hour');}else{$('.available-hour:eq(0)').addClass('selected-hour');}
App.Pages.Booking.updateSelectedHourRange();App.Pages.Booking.updateConfirmFrame();}
if(!$availableHours.find('.available-hour').length){$availableHours.text(lang('no_available_hours'));}});}
function registerAppointment(){const $captchaText=$('.captcha-text');const $altchaPayload=$('#altcha-payload');const $altchaHint=$('#altcha-hint');if($captchaText.length>0){$captchaText.removeClass('is-invalid');if($captchaText.val()===''){$captchaText.addClass('is-invalid');$captchaHint.text(lang('captcha_is_wrong')).fadeTo(400,1);setTimeout(()=>{$captchaHint.fadeTo(400,0);},3000);return;}}
if($altchaPayload.length>0&&$altchaPayload.val()===''){$altchaHint.text(lang('altcha_verification_failed')).fadeTo(400,1);setTimeout(()=>{$altchaHint.fadeTo(400,0);},3000);return;}
const formData=JSON.parse($('input[name="post_data"]').val());const data={csrf_token:vars('csrf_token'),post_data:formData,};if($captchaText.length>0){data.captcha=$captchaText.val();}
if($altchaPayload.length>0&&$altchaPayload.val()){data.altcha_payload=$altchaPayload.val();}
if(vars('manage_mode')){data.exclude_appointment_id=vars('appointment_data').id;}
const url=bookingEndpoint('register');const $layer=$('<div/>');$.ajax({url:url,method:'post',data:data,dataType:'json',beforeSend:()=>{$layer.appendTo('body').css({background:'white',position:'fixed',top:'0',left:'0',height:'100vh',width:'100vw',opacity:'0.5',});},}).done((response)=>{if(response.captcha_verification===false){$captchaHint.text(lang('captcha_is_wrong')).fadeTo(400,1);setTimeout(()=>{$captchaHint.fadeTo(400,0);},3000);$captchaTitle.find('button').trigger('click');$captchaText.addClass('is-invalid');return false;}
if(response.altcha_verification===false){$altchaHint.text(lang('altcha_verification_failed')).fadeTo(400,1);setTimeout(()=>{$altchaHint.fadeTo(400,0);},3000);if(App.Utils.Altcha){App.Utils.Altcha.reset('altcha-widget');}
return false;}
window.location.href=App.Utils.Url.siteUrl('booking_confirmation/of/'+response.appointment_hash);}).fail(()=>{$captchaTitle.find('button').trigger('click');}).always(()=>{$layer.remove();});}
function getUnavailableDates(providerId,serviceId,selectedDateString,monthChangeStep=1){if(processingUnavailableDates){return;}
if(!providerId||!serviceId){return;}
const appointmentId=App.Pages.Booking.manageMode?vars('appointment_data').id:null;const url=bookingEndpoint('get_unavailable_dates');const data={provider_id:providerId,service_id:serviceId,selected_date:encodeURIComponent(selectedDateString),csrf_token:vars('csrf_token'),manage_mode:Number(App.Pages.Booking.manageMode),appointment_id:appointmentId,};$.ajax({url:url,type:'GET',data:data,dataType:'json',}).done((response)=>{if(response.is_month_unavailable){if(!searchedMonthStart){searchedMonthStart=selectedDateString;}
if(searchedMonthCounter>=MONTH_SEARCH_LIMIT){const selectedDateMoment=moment(searchedMonthStart);const startOfMonthMoment=selectedDateMoment.clone().startOf('month');const endOfMonthMoment=selectedDateMoment.clone().endOf('month');const unavailableDates=[];while(startOfMonthMoment.isSameOrBefore(endOfMonthMoment)){unavailableDates.push(startOfMonthMoment.format('YYYY-MM-DD'));startOfMonthMoment.add(Math.abs(monthChangeStep),'days');}
applyUnavailableDates(unavailableDates,searchedMonthStart,true);searchedMonthStart=undefined;searchedMonthCounter=0;return;}
searchedMonthCounter++;const selectedDateMoment=moment(selectedDateString);selectedDateMoment.add(monthChangeStep,'month');const nextSelectedDate=selectedDateMoment.format('YYYY-MM-DD');getUnavailableDates(providerId,serviceId,nextSelectedDate,monthChangeStep);return;}
unavailableDatesBackup=response;selectedDateStringBackup=selectedDateString;applyUnavailableDates(response,selectedDateString,true);}).fail(()=>{$selectDate.parent().fadeTo(400,1);});}
function applyPreviousUnavailableDates(){applyUnavailableDates(unavailableDatesBackup,selectedDateStringBackup);}
function applyUnavailableDates(unavailableDates,selectedDateString,setDate){setDate=setDate||false;$selectDate.parent().fadeTo(400,1);processingUnavailableDates=true;const selectedDateMoment=moment(selectedDateString);const selectedDate=selectedDateMoment.toDate();const numberOfDays=selectedDateMoment.daysInMonth();if(unavailableDates.length===numberOfDays){$availableHours.text(lang('no_available_hours'));}
$selectDate[0]._flatpickr.set('disable',unavailableDates.map((unavailableDate)=>new Date(unavailableDate+'T00:00')),);if(setDate&&!vars('manage_mode')){for(let i=1;i<=numberOfDays;i++){const currentDate=new Date(selectedDate.getFullYear(),selectedDate.getMonth(),i);if(unavailableDates.indexOf(moment(currentDate).format('YYYY-MM-DD'))===-1){App.Utils.UI.setDateTimePickerValue($selectDate,currentDate);getAvailableHours(moment(currentDate).format('YYYY-MM-DD'));break;}}}
const dateQueryParam=App.Utils.Url.queryParam('date');if(dateQueryParam){const dateQueryParamMoment=moment(dateQueryParam);if(dateQueryParamMoment.isValid()&&!unavailableDates.includes(dateQueryParam)&&dateQueryParamMoment.format('YYYY-MM')===selectedDateMoment.format('YYYY-MM')){App.Utils.UI.setDateTimePickerValue($selectDate,dateQueryParamMoment.toDate());}}
searchedMonthStart=undefined;searchedMonthCounter=0;processingUnavailableDates=false;}
function deletePersonalInformation(customerToken){const url=App.Utils.Url.siteUrl('privacy/delete_personal_information');const data={csrf_token:vars('csrf_token'),customer_token:customerToken,};$.post(url,data).done(()=>{window.location.href=vars('base_url');});}
return{registerAppointment,getAvailableHours,getUnavailableDates,applyPreviousUnavailableDates,deletePersonalInformation,};})();